INSERT INTO dossier_claims (ticker,section,claim_type,claim,why_it_matters,source_title,source_url,source_excerpt,evidence_date,status,verified_by,verified_at,updated_at)
VALUES ('GILD','bull_case','editorial_analysis','A leading HIV franchise, antiviral expertise, cash generation, and commercial infrastructure can fund pipeline diversification. Long-acting HIV, prevention, oncology, and inflammation assets can extend growth beyond the existing portfolio. Visible progress in hiv and oncology can improve the durability and quality of earnings. Disciplined reinvestment and capital allocation can convert operating progress into per-share value.','Preserves the constructive interpretation as a sourced, reviewable claim.','GILD investor relations','https://investors.gilead.com/','Official earnings releases, presentations, events, governance materials, and shareholder information published by the company.','2026-08-02','published','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
