INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('GS','published','{"ticker":"GS","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.goldmansachs.com/pressroom","description":"Global investment bank and asset manager serving corporations, governments, institutions, and wealthy clients.","lede":"GOLDMAN SACHS GROUP Inc. earns owner value through fees, trading and financing revenue, asset-management fees, net interest, and investment gains. The three questions that matter most are announced backlog, m&a completion, underwriting volume, and fee share, client activity, financing balances, trading share, and risk usage, assets under supervision, fundraising, management fees, realizations, and credit losses.","sells":"Advisory, underwriting, trading, financing, market making, asset management, wealth management, and private investments.","revenueModel":"Fees, trading and financing revenue, asset-management fees, net interest, and investment gains.","opportunity":"Capital-markets normalization, fundraising, private-credit growth, and balance-sheet efficiency can lift returns.","mustGoRight":"Fee backlogs must convert, asset-management fundraising must scale, and market, credit, and operational losses must remain contained.","editorNote":"Treat the claimed advantage—client relationships, risk expertise, talent, global distribution, and a large alternatives platform can sustain premium franchises.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Client relationships, risk expertise, talent, global distribution, and a large alternatives platform can sustain premium franchises.","Capital-markets normalization, fundraising, private-credit growth, and balance-sheet efficiency can lift returns.","Visible progress in investment banking and global markets can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Market and counterparty risk can weaken the owner outcome; monitor value-at-risk, stressed exposure, derivatives, and loss events.","Private-asset marks can weaken the owner outcome; monitor realizations, impairments, vintage returns, and fundraising.","Regulatory and conduct risk can weaken the owner outcome; monitor capital rules, enforcement, litigation, and remediation.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if normalized returns remain below the cost of capital because of structural capital intensity, compliance cost, or franchise erosion.","financialDrivers":[{"label":"INVESTMENT BANKING","value":"Primary owner KPI","detail":"announced backlog, M&A completion, underwriting volume, and fee share"},{"label":"GLOBAL MARKETS","value":"Primary owner KPI","detail":"client activity, financing balances, trading share, and risk usage"},{"label":"ASSET MANAGEMENT","value":"Primary owner KPI","detail":"assets under supervision, fundraising, management fees, realizations, and credit losses"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Market and counterparty risk","level":"High","text":"Market and counterparty risk can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"value-at-risk, stressed exposure, derivatives, and loss events"},{"title":"Private-asset marks","level":"High","text":"Private-asset marks can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"realizations, impairments, vintage returns, and fundraising"},{"title":"Regulatory and conduct risk","level":"High","text":"Regulatory and conduct risk can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"capital rules, enforcement, litigation, and remediation"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"INVESTMENT BANKING","text":"Track announced backlog, m&a completion, underwriting volume, and fee share and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"GLOBAL MARKETS","text":"Track client activity, financing balances, trading share, and risk usage and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"ASSET MANAGEMENT","text":"Track assets under supervision, fundraising, management fees, realizations, and credit losses and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies investment banking?","What would cause global markets to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in asset management?","Where does GOLDMAN SACHS GROUP Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"MORGAN STANLEY, JPMORGAN CHASE & CO, BANK OF AMERICA CORP, CITIGROUP INC, BlackRock, Inc., Blackstone Inc.","comparables":[{"name":"MORGAN STANLEY","ticker":"MS","ownership":"Public","relationship":"Operating and valuation reference for GS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000895421&owner=exclude"},{"name":"JPMORGAN CHASE & CO","ticker":"JPM","ownership":"Public","relationship":"Operating and valuation reference for GS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000019617&owner=exclude"},{"name":"BANK OF AMERICA CORP","ticker":"BAC","ownership":"Public","relationship":"Operating and valuation reference for GS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000070858&owner=exclude"},{"name":"CITIGROUP INC","ticker":"C","ownership":"Public","relationship":"Operating and valuation reference for GS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000831001&owner=exclude"},{"name":"BlackRock, Inc.","ticker":"BLK","ownership":"Public","relationship":"Operating and valuation reference for GS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0002012383&owner=exclude"},{"name":"Blackstone Inc.","ticker":"BX","ownership":"Public","relationship":"Operating and valuation reference for GS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001393818&owner=exclude"}],"sources":[{"title":"GS SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000886982&owner=exclude","excerpt":"GOLDMAN SACHS GROUP INC filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"GS annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0