INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('HD','published','{"ticker":"HD","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://corporate.homedepot.com/newsroom","description":"Large home-improvement retailer serving do-it-yourself customers and professional contractors.","lede":"HOME DEPOT Inc. earns owner value through store and digital merchandise sales plus installation, delivery, credit, and professional-customer services. The three questions that matter most are transactions, average ticket, category mix, and regional housing activity, srs integration, contractor wallet share, delivery, credit, and complex-project demand, inventory turns, labor, shrink, fulfillment cost, and sales per square foot.","sells":"Building materials, hardware, appliances, tools, décor, garden products, installation, delivery, and professional services.","revenueModel":"Store and digital merchandise sales plus installation, delivery, credit, and professional-customer services.","opportunity":"Professional contractor share, housing repair demand, distribution investment, and digital fulfillment can expand wallet share.","mustGoRight":"Comparable transactions and ticket must stabilize, professional investments must earn returns, and inventory and labor must remain productive.","editorNote":"Treat the claimed advantage—store density, product breadth, professional relationships, supply chain, and omnichannel fulfillment can reinforce scale advantages.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Store density, product breadth, professional relationships, supply chain, and omnichannel fulfillment can reinforce scale advantages.","Professional contractor share, housing repair demand, distribution investment, and digital fulfillment can expand wallet share.","Visible progress in comparable sales and pro customer can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Housing and project cycle can weaken the owner outcome; monitor existing-home turnover, rates, repair spending, and large-project demand.","SRS integration can weaken the owner outcome; monitor synergies, retention, working capital, leverage, and service quality.","Competition and price can weaken the owner outcome; monitor low share, online substitution, promotions, and price investment.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if share gains fail to offset structurally weak housing turnover while capital intensity rises and store economics erode.","financialDrivers":[{"label":"COMPARABLE SALES","value":"Primary owner KPI","detail":"transactions, average ticket, category mix, and regional housing activity"},{"label":"PRO CUSTOMER","value":"Primary owner KPI","detail":"SRS integration, contractor wallet share, delivery, credit, and complex-project demand"},{"label":"STORE PRODUCTIVITY","value":"Primary owner KPI","detail":"inventory turns, labor, shrink, fulfillment cost, and sales per square foot"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Housing and project cycle","level":"High","text":"Housing and project cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"existing-home turnover, rates, repair spending, and large-project demand"},{"title":"SRS integration","level":"High","text":"SRS integration can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"synergies, retention, working capital, leverage, and service quality"},{"title":"Competition and price","level":"High","text":"Competition and price can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"LOW share, online substitution, promotions, and price investment"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"COMPARABLE SALES","text":"Track transactions, average ticket, category mix, and regional housing activity and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"PRO CUSTOMER","text":"Track srs integration, contractor wallet share, delivery, credit, and complex-project demand and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"STORE PRODUCTIVITY","text":"Track inventory turns, labor, shrink, fulfillment cost, and sales per square foot and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies comparable sales?","What would cause pro customer to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in store productivity?","Where does HOME DEPOT Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"LOWES COMPANIES INC, TRACTOR SUPPLY CO, Floor & Decor Holdings, Inc., Builders FirstSource, Inc., WILLIAMS SONOMA INC, Walmart Inc.","comparables":[{"name":"LOWES COMPANIES INC","ticker":"LOW","ownership":"Public","relationship":"Operating and valuation reference for HD","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with HD.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000060667&owner=exclude"},{"name":"TRACTOR SUPPLY CO","ticker":"TSCO","ownership":"Public","relationship":"Operating and valuation reference for HD","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with HD.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000916365&owner=exclude"},{"name":"Floor & Decor Holdings, Inc.","ticker":"FND","ownership":"Public","relationship":"Operating and valuation reference for HD","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with HD.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001507079&owner=exclude"},{"name":"Builders FirstSource, Inc.","ticker":"BLDR","ownership":"Public","relationship":"Operating and valuation reference for HD","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with HD.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001316835&owner=exclude"},{"name":"WILLIAMS SONOMA INC","ticker":"WSM","ownership":"Public","relationship":"Operating and valuation reference for HD","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with HD.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000719955&owner=exclude"},{"name":"Walmart Inc.","ticker":"WMT","ownership":"Public","relationship":"Operating and valuation reference for HD","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with HD.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000104169&owner=exclude"}],"sources":[{"title":"HD SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000354950&owner=exclude","excerpt":"HOME DEPOT, INC. filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"HD annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000354950&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"HD quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000354950&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"HD proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000354950&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"HD investor relations","meta":"Company primary materials","href":"https://ir.homedepot.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"HD official newsroom","meta":"Company announcements","href":"https://corporate.homedepot.com/newsroom","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000354950&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000354950&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000354950&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000354950&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://ir.homedepot.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

