INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('ISRG','published','{"ticker":"ISRG","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://isrg.intuitive.com/news-releases","description":"Robotic-surgery company providing da Vinci and Ion systems, instruments, accessories, and services.","lede":"INTUITIVE SURGICAL Inc. earns owner value through system sales and leases plus recurring instruments, accessories, service, and procedure-linked usage. The three questions that matter most are growth by specialty and geography, utilization, reimbursement, and hospital capacity, placements, leases, da vinci 5 rollout, utilization, and replacement cycle, instruments per procedure, price, service, mix, and gross margin.","sells":"Robotic surgical systems, single-use and reusable instruments, accessories, service, training, and digital tools.","revenueModel":"System sales and leases plus recurring instruments, accessories, service, and procedure-linked usage.","opportunity":"Procedure penetration, international adoption, new specialties, da Vinci 5, Ion, and digital services can expand recurring revenue.","mustGoRight":"New systems must deliver clinical and economic value, procedure growth must persist, and quality and reimbursement must remain favorable.","editorNote":"Treat the claimed advantage—a large installed base, surgeon training, clinical workflows, recurring instruments, and extensive evidence can reinforce adoption.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["A large installed base, surgeon training, clinical workflows, recurring instruments, and extensive evidence can reinforce adoption.","Procedure penetration, international adoption, new specialties, da Vinci 5, Ion, and digital services can expand recurring revenue.","Visible progress in procedures and installed base can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Competition and hospital economics can weaken the owner outcome; monitor placements, procedure cost, rival systems, contracts, and utilization.","Product quality and liability can weaken the owner outcome; monitor recalls, adverse events, training, claims, and regulatory action.","Reimbursement and evidence can weaken the owner outcome; monitor coverage, comparative outcomes, procedure guidelines, and budget pressure.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if robotic procedure economics fail to justify adoption and competitors materially weaken recurring instrument share.","financialDrivers":[{"label":"PROCEDURES","value":"Primary owner KPI","detail":"growth by specialty and geography, utilization, reimbursement, and hospital capacity"},{"label":"INSTALLED BASE","value":"Primary owner KPI","detail":"placements, leases, da Vinci 5 rollout, utilization, and replacement cycle"},{"label":"RECURRING ECONOMICS","value":"Primary owner KPI","detail":"instruments per procedure, price, service, mix, and gross margin"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Competition and hospital economics","level":"High","text":"Competition and hospital economics can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"placements, procedure cost, rival systems, contracts, and utilization"},{"title":"Product quality and liability","level":"High","text":"Product quality and liability can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"recalls, adverse events, training, claims, and regulatory action"},{"title":"Reimbursement and evidence","level":"High","text":"Reimbursement and evidence can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"coverage, comparative outcomes, procedure guidelines, and budget pressure"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"PROCEDURES","text":"Track growth by specialty and geography, utilization, reimbursement, and hospital capacity and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"INSTALLED BASE","text":"Track placements, leases, da vinci 5 rollout, utilization, and replacement cycle and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"RECURRING ECONOMICS","text":"Track instruments per procedure, price, service, mix, and gross margin and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies procedures?","What would cause installed base to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in recurring economics?","Where does INTUITIVE SURGICAL Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Medtronic plc, STRYKER CORP, JOHNSON & JOHNSON, BOSTON SCIENTIFIC CORP, ABBOTT LABORATORIES, ZIMMER BIOMET HOLDINGS, INC.","comparables":[{"name":"Medtronic plc","ticker":"MDT","ownership":"Public","relationship":"Operating and valuation reference for ISRG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ISRG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001613103&owner=exclude"},{"name":"STRYKER CORP","ticker":"SYK","ownership":"Public","relationship":"Operating and valuation reference for ISRG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ISRG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000310764&owner=exclude"},{"name":"JOHNSON & JOHNSON","ticker":"JNJ","ownership":"Public","relationship":"Operating and valuation reference for ISRG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ISRG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000200406&owner=exclude"},{"name":"BOSTON SCIENTIFIC CORP","ticker":"BSX","ownership":"Public","relationship":"Operating and valuation reference for ISRG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ISRG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000885725&owner=exclude"},{"name":"ABBOTT LABORATORIES","ticker":"ABT","ownership":"Public","relationship":"Operating and valuation reference for ISRG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ISRG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000001800&owner=exclude"},{"name":"ZIMMER BIOMET HOLDINGS, INC.","ticker":"ZBH","ownership":"Public","relationship":"Operating and valuation reference for ISRG","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ISRG.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001136869&owner=exclude"}],"sources":[{"title":"ISRG SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001035267&owner=exclude","excerpt":"INTUITIVE SURGICAL INC filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"ISRG annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001035267&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"ISRG quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001035267&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"ISRG proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001035267&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"ISRG investor relations","meta":"Company primary materials","href":"https://isrg.intuitive.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"ISRG official newsroom","meta":"Company announcements","href":"https://isrg.intuitive.com/news-releases","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001035267&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001035267&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001035267&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001035267&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://isrg.intuitive.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

