INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('KLAC','published','{"ticker":"KLAC","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.kla.com/advance","description":"Semiconductor process-control company focused on inspection, metrology, data analytics, and specialty-process equipment.","lede":"KLA Corp. earns owner value through capital-equipment sales plus recurring service, spare-parts, software, and support revenue. The three questions that matter most are inspection and metrology spend per wafer start, node, and packaging layer, foundry, logic, memory, geography, and project timing, installed base, utilization, attach, parts, pricing, and recurring margin.","sells":"Wafer and reticle inspection, metrology, computational analytics, specialty semiconductor equipment, services, and parts.","revenueModel":"Capital-equipment sales plus recurring service, spare-parts, software, and support revenue.","opportunity":"Advanced logic, memory, packaging, and rising process-control intensity can expand content per wafer-fab project.","mustGoRight":"Customers must sustain advanced-node and packaging investment, product cadence must preserve technical leadership, and service revenue must remain resilient.","editorNote":"Treat the claimed advantage—process complexity and yield economics can make inspection and metrology mission-critical with high switching costs.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Process complexity and yield economics can make inspection and metrology mission-critical with high switching costs.","Advanced logic, memory, packaging, and rising process-control intensity can expand content per wafer-fab project.","Visible progress in process-control intensity and customer capex can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Customer concentration and cycle can weaken the owner outcome; monitor top customers, capex plans, memory cycle, and order pushouts.","Export controls can weaken the owner outcome; monitor china revenue, licenses, product restrictions, and service limitations.","Technology execution can weaken the owner outcome; monitor roadmap, qualification, throughput, sensitivity, and competitive wins.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if process-control intensity stalls and competitors displace KLA at leading customers while service attachment weakens.","financialDrivers":[{"label":"PROCESS-CONTROL INTENSITY","value":"Primary owner KPI","detail":"inspection and metrology spend per wafer start, node, and packaging layer"},{"label":"CUSTOMER CAPEX","value":"Primary owner KPI","detail":"foundry, logic, memory, geography, and project timing"},{"label":"SERVICE","value":"Primary owner KPI","detail":"installed base, utilization, attach, parts, pricing, and recurring margin"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Customer concentration and cycle","level":"High","text":"Customer concentration and cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"top customers, capex plans, memory cycle, and order pushouts"},{"title":"Export controls","level":"High","text":"Export controls can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"China revenue, licenses, product restrictions, and service limitations"},{"title":"Technology execution","level":"High","text":"Technology execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"roadmap, qualification, throughput, sensitivity, and competitive wins"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"PROCESS-CONTROL INTENSITY","text":"Track inspection and metrology spend per wafer start, node, and packaging layer and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"CUSTOMER CAPEX","text":"Track foundry, logic, memory, geography, and project timing and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"SERVICE","text":"Track installed base, utilization, attach, parts, pricing, and recurring margin and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies process-control intensity?","What would cause customer capex to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in service?","Where does KLA Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"APPLIED MATERIALS INC /DE, LAM RESEARCH CORP, ASML HOLDING NV, TERADYNE, INC, ONTO INNOVATION INC., AXCELIS TECHNOLOGIES INC","comparables":[{"name":"APPLIED MATERIALS INC /DE","ticker":"AMAT","ownership":"Public","relationship":"Operating and valuation reference for KLAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KLAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000006951&owner=exclude"},{"name":"LAM RESEARCH CORP","ticker":"LRCX","ownership":"Public","relationship":"Operating and valuation reference for KLAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KLAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000707549&owner=exclude"},{"name":"ASML HOLDING NV","ticker":"ASML","ownership":"Public","relationship":"Operating and valuation reference for KLAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KLAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000937966&owner=exclude"},{"name":"TERADYNE, INC","ticker":"TER","ownership":"Public","relationship":"Operating and valuation reference for KLAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KLAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000097210&owner=exclude"},{"name":"ONTO INNOVATION INC.","ticker":"ONTO","ownership":"Public","relationship":"Operating and valuation reference for KLAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KLAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000704532&owner=exclude"},{"name":"AXCELIS TECHNOLOGIES INC","ticker":"ACLS","ownership":"Public","relationship":"Operating and valuation reference for KLAC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KLAC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001113232&owner=exclude"}],"sources":[{"title":"KLAC SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000319201&owner=exclude","excerpt":"KLA CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"KLAC annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000319201&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"KLAC quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000319201&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"KLAC proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000319201&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"KLAC investor relations","meta":"Company primary materials","href":"https://ir.kla.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"KLAC official newsroom","meta":"Company announcements","href":"https://www.kla.com/advance","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000319201&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000319201&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000319201&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000319201&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://ir.kla.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

