INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('LIN','published','{"ticker":"LIN","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.linde.com/news-media","description":"Global industrial-gases and engineering company serving manufacturing, health care, electronics, energy, and food markets.","lede":"LINDE PLC earns owner value through on-site long-term contracts, merchant liquid sales, packaged gases, equipment, and engineering projects. The three questions that matter most are backlog, startup, contract terms, volumes, customer credit, and returns, pricing, energy pass-through, density, plant utilization, and cost savings, project sanctions, customer ramps, subsidies, hydrogen, and specialty-gas demand.","sells":"Oxygen, nitrogen, hydrogen, argon, specialty gases, medical gases, equipment, and plant engineering.","revenueModel":"On-site long-term contracts, merchant liquid sales, packaged gases, equipment, and engineering projects.","opportunity":"Electronics, clean energy, health care, and industrial investment can add contracted projects and network density.","mustGoRight":"New projects must meet return thresholds, pricing must offset energy and inflation, and customer concentration must remain manageable.","editorNote":"Treat the claimed advantage—dense distribution, customer-integrated plants, long contracts, and engineering scale can support stable pricing and returns.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Dense distribution, customer-integrated plants, long contracts, and engineering scale can support stable pricing and returns.","Electronics, clean energy, health care, and industrial investment can add contracted projects and network density.","Visible progress in on-site projects and price & productivity can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Project and customer exposure can weaken the owner outcome; monitor cost, schedule, take-or-pay terms, counterparty credit, and utilization.","Energy and currency can weaken the owner outcome; monitor pass-through, power and feedstock cost, hedging, and translation.","Industrial cycle can weaken the owner outcome; monitor volumes, plant utilization, customer shutdowns, and merchant pricing.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if capital-heavy projects repeatedly earn inadequate returns or contract protections fail during customer distress and energy volatility.","financialDrivers":[{"label":"ON-SITE PROJECTS","value":"Primary owner KPI","detail":"backlog, startup, contract terms, volumes, customer credit, and returns"},{"label":"PRICE & PRODUCTIVITY","value":"Primary owner KPI","detail":"pricing, energy pass-through, density, plant utilization, and cost savings"},{"label":"ELECTRONICS & CLEAN ENERGY","value":"Primary owner KPI","detail":"project sanctions, customer ramps, subsidies, hydrogen, and specialty-gas demand"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Project and customer exposure","level":"High","text":"Project and customer exposure can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"cost, schedule, take-or-pay terms, counterparty credit, and utilization"},{"title":"Energy and currency","level":"High","text":"Energy and currency can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"pass-through, power and feedstock cost, hedging, and translation"},{"title":"Industrial cycle","level":"High","text":"Industrial cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"volumes, plant utilization, customer shutdowns, and merchant pricing"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"ON-SITE PROJECTS","text":"Track backlog, startup, contract terms, volumes, customer credit, and returns and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"PRICE & PRODUCTIVITY","text":"Track pricing, energy pass-through, density, plant utilization, and cost savings and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"ELECTRONICS & CLEAN ENERGY","text":"Track project sanctions, customer ramps, subsidies, hydrogen, and specialty-gas demand and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies on-site projects?","What would cause price & productivity to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in electronics & clean energy?","Where does LINDE PLC have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Air Products & Chemicals, Inc., AIQUY, SHERWIN WILLIAMS CO, ECOLAB INC., DuPont de Nemours, Inc., DOW INC.","comparables":[{"name":"Air Products & Chemicals, Inc.","ticker":"APD","ownership":"Public","relationship":"Operating and valuation reference for LIN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LIN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000002969&owner=exclude"},{"name":"AIQUY","ticker":"AIQUY","ownership":"Public","relationship":"Operating and valuation reference for LIN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LIN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AIQUY&owner=exclude"},{"name":"SHERWIN WILLIAMS CO","ticker":"SHW","ownership":"Public","relationship":"Operating and valuation reference for LIN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LIN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000089800&owner=exclude"},{"name":"ECOLAB INC.","ticker":"ECL","ownership":"Public","relationship":"Operating and valuation reference for LIN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LIN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000031462&owner=exclude"},{"name":"DuPont de Nemours, Inc.","ticker":"DD","ownership":"Public","relationship":"Operating and valuation reference for LIN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LIN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001666700&owner=exclude"},{"name":"DOW INC.","ticker":"DOW","ownership":"Public","relationship":"Operating and valuation reference for LIN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LIN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001751788&owner=exclude"}],"sources":[{"title":"LIN SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001707925&owner=exclude","excerpt":"LINDE PLC filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"LIN annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001707925&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"LIN quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001707925&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"LIN proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001707925&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"LIN investor relations","meta":"Company primary materials","href":"https://investors.linde.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"LIN official newsroom","meta":"Company announcements","href":"https://www.linde.com/news-media","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001707925&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001707925&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001707925&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001707925&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.linde.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

